package com.nexus.access.backend.place;
import java.time.OffsetDateTime; import java.util.UUID; import jakarta.persistence.*; import org.locationtech.jts.geom.Point;
@Entity @Table(name="places") public class Place { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,length=200) private String name; @Column(columnDefinition="text") private String description; @Column(length=255) private String address; @Column(length=120) private String city; @Column(length=120) private String district; @Column(name="place_type",nullable=false,length=80) private String placeType; @Column(name="accessibility_score",nullable=false) private int accessibilityScore; @Column(nullable=false,columnDefinition="geography(Point,4326)") private Point location; @Column(name="is_active",nullable=false) private boolean active=true; @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; @PrePersist void c(){createdAt=OffsetDateTime.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=OffsetDateTime.now();} public UUID getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getDistrict(){return district;} public void setDistrict(String v){district=v;} public String getPlaceType(){return placeType;} public void setPlaceType(String v){placeType=v;} public int getAccessibilityScore(){return accessibilityScore;} public void setAccessibilityScore(int v){accessibilityScore=v;} public Point getLocation(){return location;} public void setLocation(Point v){location=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;} }
